    {
      "claim": "Multiple failed SSH login attempts for the account 'svc_backup' from the same IP address",
      "evidence": ["E1", "E2", "E3", "E4", "E5"]
    },
    {
      "claim": "Successful SSH login for the account 'svc_backup' from the IP address 192.168.56.1",
      "evidence": ["E6"]
    },
    {
      "claim": "The attacker used sudo to run a command that reads /etc/shadow and writes a specific string to a temporary file",
      "evidence": ["E7"]
    }
  ],
